// Keep the exposed state in sync with the sequencer state object. The
    // previous bare identifiers were never declared and stopped startup.
    window.gameState = { title: "Sound Painter 2", activeTrack: state.activeTrack, bpm: state.bpm, isPlaying: state.isPlaying };

    window.game = window.gameState;





    function initAudio() {
        if (audioCtx) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            return;
        }
        
        audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        if (audioCtx.state === 'suspended') {
            audioCtx.resume();
        }
        
        // 1. Create Master Output Chain
        masterAnalyser = audioCtx.createAnalyser();
        masterAnalyser.fftSize = 256;
        
        masterGain = audioCtx.createGain();
        masterGain.gain.value = 0.8;
        
        mainFilter = audioCtx.createBiquadFilter();
        mainFilter.type = 'lowpass';
        mainFilter.frequency.value = state.settings.cutoff;
        mainFilter.Q.value = state.settings.resonance;

        // 2. Create Delay FX Routing
        delayNode = audioCtx.createDelay(2.0);
        delayNode.delayTime.value = state.settings.delayTime;
        
        delayFeedbackNode = audioCtx.createGain();
        delayFeedbackNode.gain.value = state.settings.delayFeedback;
        
        delayFilter = audioCtx.createBiquadFilter();
        delayFilter.type = 'bandpass';
        delayFilter.frequency.value = 1000;
        delayFilter.Q.value = 0.8;
        
        delayGainNode = audioCtx.createGain();
        delayGainNode.gain.value = state.settings.delayGain;
        
        // Connect delay feedback loop
        delayNode.connect(delayFilter);
        delayFilter.connect(delayFeedbackNode);
        delayFeedbackNode.connect(delayNode);
        
        // 3. Create Reverb FX Routing
        reverbNode = audioCtx.createConvolver();
        reverbGainNode = audioCtx.createGain();
        reverbGainNode.gain.value = state.settings.reverbGain;
        
        // Generate synthetic impulse response for reverb
        const impulseLen = audioCtx.sampleRate * 2.5; // 2.5 seconds reverb tail
        const impulseBuffer = audioCtx.createBuffer(2, impulseLen, audioCtx.sampleRate);
        for (let channel = 0; channel < 2; channel++) {
            const data = impulseBuffer.getChannelData(channel);
            for (let i = 0; i < impulseLen; i++) {
                // Exponential decay white noise
                data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / impulseLen, 2.5);
            }
        }
        reverbNode.buffer = impulseBuffer;

        // 4. Connect FX sends
        // Connections: mainFilter -> Reverb & Delay
        // mainFilter -> masterAnalyser -> masterGain -> destination
        mainFilter.connect(masterAnalyser);
        masterAnalyser.connect(masterGain);
        masterGain.connect(audioCtx.destination);
        
        // FX sends from Main Filter
        mainFilter.connect(delayNode);
        delayNode.connect(delayGainNode);
        delayGainNode.connect(masterAnalyser);
        
        mainFilter.connect(reverbNode);
        reverbNode.connect(reverbGainNode);
        reverbGainNode.connect(masterAnalyser);

        // 5. Build mixer tracks
        TRACKS.forEach(t => {
            const trackGain = audioCtx.createGain();
            trackGain.gain.value = state.settings.vol[t];
            
            const trackPanner = audioCtx.createStereoPanner ? audioCtx.createStereoPanner() : null;
            if (trackPanner) {
                trackPanner.pan.value = state.settings.pan[t];
                trackGain.connect(trackPanner);
                trackPanner.connect(mainFilter);
            } else {
                trackGain.connect(mainFilter);
            }
            
            channels[t].gain = trackGain;
            channels[t].panner = trackPanner;
        });

        // Initialize white noise buffer
        getNoiseBuffer();
    }

// -------------------------------------------------------------
    // 4. DYNAMIC SYNTH DRUM VOICES
    // -------------------------------------------------------------
    function playKick(time, v) {
        const vv = Math.max(0.15, Math.min(1, typeof v === 'number' ? v : 1));
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.connect(gain);
        gain.connect(channels.drums.gain);

        osc.frequency.setValueAtTime(150, time);
        // Exponential sweep down for standard kick thump
        osc.frequency.exponentialRampToValueAtTime(0.01, time + 0.3);

        gain.gain.setValueAtTime(0.3 + 0.7 * vv, time);
        gain.gain.exponentialRampToValueAtTime(0.01, time + 0.3);

        osc.start(time);
        osc.stop(time + 0.3);
    }

function playSnare(time, v) {
        const vv = Math.max(0.15, Math.min(1, typeof v === 'number' ? v : 1));
        // Noise source
        const noise = audioCtx.createBufferSource();
        noise.buffer = getNoiseBuffer();
        
        const noiseFilter = audioCtx.createBiquadFilter();
        noiseFilter.type = 'highpass';
        noiseFilter.frequency.value = 1000;
        
        const noiseGain = audioCtx.createGain();
        noiseGain.gain.setValueAtTime(0.15 + 0.55 * vv, time);
        noiseGain.gain.exponentialRampToValueAtTime(0.01, time + 0.25);
        
        noise.connect(noiseFilter);
        noiseFilter.connect(noiseGain);
        noiseGain.connect(channels.drums.gain);

        // Snap body (sine tone)
        const snap = audioCtx.createOscillator();
        const snapGain = audioCtx.createGain();
        snap.type = 'triangle';
        snap.frequency.setValueAtTime(180, time);
        snap.frequency.exponentialRampToValueAtTime(100, time + 0.1);
        
        snapGain.gain.setValueAtTime(0.1 + 0.4 * vv, time);
        snapGain.gain.exponentialRampToValueAtTime(0.01, time + 0.1);
        
        snap.connect(snapGain);
        snapGain.connect(channels.drums.gain);

        noise.start(time);
        snap.start(time);
        noise.stop(time + 0.25);
        snap.stop(time + 0.1);
    }

function playHihat(time, isClosed, v) {
        if (typeof isClosed !== 'boolean') { v = isClosed; isClosed = true; }
        const vv = Math.max(0.15, Math.min(1, typeof v === 'number' ? v : 1));
        const source = audioCtx.createBufferSource();
        source.buffer = getNoiseBuffer();

        const filter = audioCtx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.frequency.value = 7500;
        filter.Q.value = 3;

        const gain = audioCtx.createGain();
        const duration = isClosed ? 0.05 : 0.25;
        
        gain.gain.setValueAtTime(0.06 + 0.24 * vv, time);
        gain.gain.exponentialRampToValueAtTime(0.001, time + duration);

        source.connect(filter);
        filter.connect(gain);
        gain.connect(channels.drums.gain);

        source.start(time);
        source.stop(time + duration);
    }

function playPerc1(time, v) {
        const vv = Math.max(0.15, Math.min(1, typeof v === 'number' ? v : 1));
        // Cowbell style ring
        const osc1 = audioCtx.createOscillator();
        const osc2 = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        
        osc1.type = 'square';
        osc2.type = 'square';
        
        osc1.frequency.setValueAtTime(800, time);
        osc2.frequency.setValueAtTime(540, time); // metallic offset
        
        gain.gain.setValueAtTime(0.06 + 0.24 * vv, time);
        gain.gain.exponentialRampToValueAtTime(0.001, time + 0.15);
        
        osc1.connect(gain);
        osc2.connect(gain);
        gain.connect(channels.drums.gain);
        
        osc1.start(time);
        osc2.start(time);
        
        osc1.stop(time + 0.15);
        osc2.stop(time + 0.15);
    }

function playPerc2(time, v) {
        const vv = Math.max(0.15, Math.min(1, typeof v === 'number' ? v : 1));
        // Woodblock style
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(900, time);
        osc.frequency.exponentialRampToValueAtTime(400, time + 0.07);
        
        gain.gain.setValueAtTime(0.1 + 0.4 * vv, time);
        gain.gain.exponentialRampToValueAtTime(0.001, time + 0.07);
        
        osc.connect(gain);
        gain.connect(channels.drums.gain);
        
        osc.start(time);
        osc.stop(time + 0.07);
    }

// -------------------------------------------------------------
    // 5. INDIVIDUAL NOTE TRIGGERS (velocity scales loudness 0.15..1)
    // -------------------------------------------------------------
    function playSynthNote(track, noteIdx, time, velocity) {
        if (!audioCtx) return;
        const vel = Math.max(0.15, Math.min(1, typeof velocity === 'number' ? velocity : 1));
        const duration = state.settings.decay;

        if (track === 'lead') {
            const frequency = LEAD_PITCHES[noteIdx];
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            
            osc.type = state.settings.waveform;
            osc.frequency.setValueAtTime(frequency, time);
            
            // Envelope attack 0.01s, decay (peak scaled by velocity)
            gain.gain.setValueAtTime(0.001, time);
            gain.gain.linearRampToValueAtTime(0.1 + 0.4 * vel, time + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.001, time + duration);
            
            osc.connect(gain);
            gain.connect(channels.lead.gain);
            
            osc.start(time);
            osc.stop(time + duration);
        }
        else if (track === 'bass') {
            const frequency = BASS_PITCHES[noteIdx];
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            
            osc.type = 'triangle'; // bass sounds clean on triangle/saw mix
            osc.frequency.setValueAtTime(frequency, time);
            
            gain.gain.setValueAtTime(0.001, time);
            gain.gain.linearRampToValueAtTime(0.15 + 0.65 * vel, time + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.001, time + duration * 1.5);
            
            osc.connect(gain);
            gain.connect(channels.bass.gain);
            
            osc.start(time);
            osc.stop(time + duration * 1.5);
        }
        else if (track === 'chords') {
            // Polyphonic Chord trigger!
            const chordFrequencies = CHORD_PITCHES[noteIdx];
            const chordDuration = duration * 2.5; // chord pads ring longer
            
            chordFrequencies.forEach(freq => {
                const osc = audioCtx.createOscillator();
                const gain = audioCtx.createGain();
                
                osc.type = 'sine'; // sine pads are nice and smooth
                osc.frequency.setValueAtTime(freq, time);
                
                // Slow attack pad envelope (peak scaled by velocity)
                gain.gain.setValueAtTime(0.001, time);
                gain.gain.linearRampToValueAtTime(0.05 + 0.2 * vel, time + 0.1);
                gain.gain.exponentialRampToValueAtTime(0.001, time + chordDuration);
                
                osc.connect(gain);
                gain.connect(channels.chords.gain);
                
                osc.start(time);
                osc.stop(time + chordDuration);
            });
        }
        else if (track === 'drums') {
            // Map index to respective drum synth voice (velocity-aware)
            switch(noteIdx) {
                case 0: playKick(time, vel); break;
                case 1: playSnare(time, vel); break;
                case 2: playHihat(time, true, vel); break;
                case 3: playHihat(time, false, vel); break;
                case 4: playClap(time, vel); break;
                case 5: playRimshot(time, vel); break;
                case 6: playPerc1(time, vel); break;
                case 7: playPerc2(time, vel); break;
            }
        }
    }



    function resetAll() {
        TRACKS.forEach(track => {
            const grid = state.grids[track];
            const vels = state.vel[track];
            for (let r = 0; r < NUM_ROWS; r++) {
                grid[r].fill(false);
                vels[r].fill(1);
            }
        });
        
        state.bpm = 120;
        state.settings.cutoff = 2000;
        state.settings.resonance = 2.0;
        state.settings.decay = 0.3;
        state.settings.waveform = 'sawtooth';
        state.settings.delayGain = 0.2;
        state.settings.delayFeedback = 0.4;
        state.settings.delayTime = 0.3;
        state.settings.reverbGain = 0.15;
        
        TRACKS.forEach(t => {
            state.settings.vol[t] = t === 'chords' ? 0.6 : (t === 'lead' || t === 'bass' ? 0.7 : 0.8);
            state.settings.pan[t] = 0;
        });

        document.getElementById('select-preset').value = '';

        updateSlidersAndDropdowns();
    }



    function scheduler() {
        while (nextNoteTime < audioCtx.currentTime + SCHEDULE_AHEAD_TIME) {
            scheduleNotes(state.currentStep, nextNoteTime);
            advanceStep();
        }
        schedulerTimer = setTimeout(scheduler, LOOKAHEAD_MS);
    }

function scheduleNotes(stepIndex, time) {
        // Visual callback sync (uses requestAnimationFrame)
        const displayStep = stepIndex;
        audioCtx.resume();
        
        // Trigger all active notes at this step index across channels
        // (skipped while muted; the playhead highlight below still advances).
        if (!isMuted) TRACKS.forEach(track => {
            const grid = state.grids[track];
            const vels = state.vel[track];
            for (let row = 0; row < NUM_ROWS; row++) {
                if (grid[row][stepIndex]) {
                    playSynthNote(track, row, time, vels[row][stepIndex]);
                }
            }
        });

        // Sync grid view highlights on the UI
        setTimeout(() => {
            highlightPlayheadColumn(displayStep);
        }, (time - audioCtx.currentTime) * 1000);
    }

function advanceStep() {
        const secondsPerBeat = 60.0 / state.bpm;
        // 16th notes: 4 steps per beat
        const stepDuration = 0.25 * secondsPerBeat;
        
        nextNoteTime += stepDuration;
        
        state.currentStep = (state.currentStep + 1) % NUM_STEPS;
    }

function syncTransportUI() {
        const mainBtn = document.getElementById('btn-play-stop');
        const pocket = document.getElementById('pocket-transport');
        const pIcon = document.getElementById('pocket-play-icon');
        const pLabel = document.getElementById('pocket-play-label');
        if (mainBtn) {
            mainBtn.classList.toggle('playing', state.isPlaying);
            const lbl = mainBtn.querySelector('.label');
            const icn = mainBtn.querySelector('.icon');
            if (lbl) lbl.textContent = state.isPlaying ? 'Stop' : 'Play';
            if (icn) icn.textContent = state.isPlaying ? '■' : '▶';
        }
        if (pocket) pocket.classList.toggle('is-playing', state.isPlaying);
        if (pIcon) pIcon.textContent = state.isPlaying ? '■' : '▶';
        if (pLabel) pLabel.textContent = state.isPlaying ? 'STOP' : 'PLAY';
    }

function toggleSequencer() {
        initAudio();
        
        if (state.isPlaying) {
            // STOP
            state.isPlaying = false;
            if (schedulerTimer) {
                clearTimeout(schedulerTimer);
                schedulerTimer = null;
            }
            state.currentStep = -1;
            removePlayheadHighlights();
            syncTransportUI();
        } else {
            // PLAY
            state.isPlaying = true;
            state.currentStep = 0;
            nextNoteTime = audioCtx.currentTime + 0.05;
            
            // Sync dynamic parameters
            updateSynthParameters();
            scheduler();
            
            syncTransportUI();
        }
    }

// Versioned composition links. Decode into a candidate before touching live audio state.
const SONG_RANGES = {
    cutoff: [100, 10000], resonance: [0, 15], decay: [0.05, 2],
    delayGain: [0, 0.8], delayFeedback: [0, 0.9], delayTime: [0.1, 1],
    reverbGain: [0, 0.8]
};
const SONG_WAVES = ['sawtooth', 'square', 'triangle', 'sine'];

function validateSongNumber(value, min, max) {
    if (!Number.isFinite(value) || value < min || value > max) throw new Error('Invalid song value');
    return value;
}

function validateSong(candidate) {
    validateSongNumber(candidate.bpm, 60, 200);
    if (!SONG_WAVES.includes(candidate.settings.waveform)) throw new Error('Invalid waveform');
    for (const [key, range] of Object.entries(SONG_RANGES)) {
        validateSongNumber(candidate.settings[key], ...range);
    }
    for (const track of TRACKS) {
        validateSongNumber(candidate.settings.vol[track], 0, 1);
        validateSongNumber(candidate.settings.pan[track], -1, 1);
        for (const key of ['grids', 'vel']) {
            const rows = candidate[key][track];
            if (!Array.isArray(rows) || rows.length !== NUM_ROWS) throw new Error('Invalid rows');
            for (const row of rows) {
                if (!Array.isArray(row) || row.length !== NUM_STEPS) throw new Error('Invalid steps');
                for (const value of row) {
                    if (key === 'grids') {
                        if (typeof value !== 'boolean') throw new Error('Invalid note');
                    } else validateSongNumber(value, 0.15, 1);
                }
            }
        }
    }
    return candidate;
}

function encodeSong(song) {
    validateSong(song);
    // Flatten each track: zero is silent; nonzero stores the note's exact velocity.
    const notes = TRACKS.map(track => song.grids[track].flatMap((row, r) =>
        row.map((on, c) => on ? song.vel[track][r][c] : 0)));
    const payload = JSON.stringify({ v: 2, bpm: song.bpm, settings: song.settings, notes });
    return 'v2.' + btoa(payload).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function decodeSong(encoded, defaults) {
    if (typeof encoded !== 'string' || encoded.length > 16000) throw new Error('Invalid link size');
    const modern = encoded.startsWith('v2.');
    const raw = modern ? encoded.slice(3) : encoded;
    if (!/^[A-Za-z0-9_-]+$/.test(raw)) throw new Error('Invalid link encoding');
    const binary = atob(raw.replace(/-/g, '+').replace(/_/g, '/'));
    const candidate = JSON.parse(JSON.stringify(defaults));
    if (modern) {
        const data = JSON.parse(binary);
        if (data.v !== 2 || !Array.isArray(data.notes) || data.notes.length !== TRACKS.length) {
            throw new Error('Unsupported song format');
        }
        candidate.bpm = data.bpm;
        candidate.settings = data.settings;
        TRACKS.forEach((track, t) => {
            const notes = data.notes[t];
            if (!Array.isArray(notes) || notes.length !== NUM_ROWS * NUM_STEPS) throw new Error('Invalid notes');
            candidate.grids[track] = [];
            candidate.vel[track] = [];
            for (let row = 0; row < NUM_ROWS; row++) {
                const values = notes.slice(row * NUM_STEPS, (row + 1) * NUM_STEPS);
                values.forEach(value => { if (value !== 0) validateSongNumber(value, 0.15, 1); });
                candidate.grids[track].push(values.map(value => value !== 0));
                candidate.vel[track].push(values.map(value => value || 1));
            }
        });
    } else {
        // Original links contain 64 note bytes and optionally all nine synth bytes.
        if (binary.length !== 64 && binary.length !== 73) throw new Error('Truncated legacy song');
        const bytes = Uint8Array.from(binary, c => c.charCodeAt(0));
        let offset = 0;
        for (const track of TRACKS) {
            for (let row = 0; row < NUM_ROWS; row++) {
                const word = bytes[offset++] | (bytes[offset++] << 8);
                candidate.grids[track][row] = Array.from({ length: NUM_STEPS }, (_, c) => !!(word & (1 << c)));
                candidate.vel[track][row].fill(1);
            }
        }
        if (bytes.length === 73) {
            candidate.bpm = bytes[offset++];
            // Old cutoff quantization rounded 100 Hz down to 80 Hz.
            candidate.settings.cutoff = Math.max(100, bytes[offset++] * 40);
            candidate.settings.resonance = bytes[offset++] / 15;
            candidate.settings.decay = bytes[offset++] / 100;
            candidate.settings.waveform = SONG_WAVES[bytes[offset++]];
            for (const key of ['delayGain', 'delayFeedback', 'delayTime', 'reverbGain']) {
                candidate.settings[key] = bytes[offset++] / 100;
            }
        }
    }
    return validateSong(candidate);
}

function serializeState() {
    return encodeSong(state);
}

function deserializeState(encoded) {
    try {
        const song = decodeSong(encoded, state);
        state.bpm = song.bpm;
        state.settings = song.settings;
        state.grids = song.grids;
        state.vel = song.vel;
        return true;
    } catch {
        return false;
    }
}

function showShareStatus(message, link) {
    const banner = document.getElementById('share-banner');
    banner.replaceChildren(document.createTextNode(message));
    banner.setAttribute('role', 'status');
    banner.classList.remove('hidden');
    const dismiss = document.createElement('button');
    dismiss.type = 'button';
    dismiss.textContent = 'Dismiss';
    dismiss.className = 'studio-page-button';
    dismiss.style.marginLeft = '8px';
    dismiss.addEventListener('click', () => banner.classList.add('hidden'));
    banner.append(dismiss);
    if (link) {
        const input = document.createElement('input');
        input.type = 'text';
        input.readOnly = true;
        input.value = link;
        input.setAttribute('aria-label', 'Song sharing link');
        input.style.cssText = 'width:100%;color:#111;background:#fff;padding:6px;';
        banner.append(input);
        input.focus();
        input.select();
    }
}

function loadFromUrlParameters() {
    const data = new URLSearchParams(window.location.search).get('data');
    if (!data) return;
    if (deserializeState(data)) {
        updateSlidersAndDropdowns();
    } else {
        showShareStatus('This song link is incomplete or unsupported. Your current pattern is unchanged.');
    }
}

async function shareSong() {
    const url = new URL(window.location.href);
    url.search = '';
    url.hash = '';
    url.searchParams.set('data', serializeState());
    const link = url.toString();
    try {
        await navigator.clipboard.writeText(link);
        showShareStatus('Song link copied. Notes, dynamics, mix, and synth settings are included.');
    } catch {
        showShareStatus('Copy this song link:', link);
    }
}



    // -------------------------------------------------------------
    // 9. UI BINDINGS, RENDER LOGIC & EVENT LISTENERS
    // -------------------------------------------------------------

    function buildSequencerUI() {
        const labelsContainer = document.getElementById('sequencer-y-labels');
        const gridContainer = document.getElementById('sequencer-grid');
        const indicatorContainer = document.querySelector('.steps-indicators-grid');
        
        labelsContainer.innerHTML = '';
        gridContainer.innerHTML = '';
        indicatorContainer.innerHTML = '';

        // Playhead indicator nodes
        for (let s = 0; s < NUM_STEPS; s++) {
            const node = document.createElement('div');
            node.className = 'step-indicator-node';
            node.id = `step-node-${s}`;
            indicatorContainer.appendChild(node);
        }

        // Labels for rows depending on active track
        let rowNames = [];
        if (state.activeTrack === 'lead') rowNames = ['C5', 'A4', 'G4', 'E4', 'D4', 'C4', 'A3', 'G3'];
        if (state.activeTrack === 'bass') rowNames = ['C3', 'Bb2', 'Ab2', 'G2', 'F2', 'Eb2', 'D2', 'C2'];
        if (state.activeTrack === 'chords') rowNames = CHORD_NAMES;
        if (state.activeTrack === 'drums') rowNames = DRUM_NAMES;

        for (let row = 0; row < NUM_ROWS; row++) {
            const lbl = document.createElement('div');
            lbl.className = 'pitch-row-label';
            lbl.textContent = rowNames[row];
            labelsContainer.appendChild(lbl);
            
            const rowDiv = document.createElement('div');
            rowDiv.className = 'sequencer-row-grid';
            rowDiv.id = `grid-row-${row}`;
            
            for (let col = 0; col < NUM_STEPS; col++) {
                const cell = document.createElement('div');
                cell.className = 'sequencer-cell';
                cell.dataset.row = row;
                cell.dataset.col = col;
                cell.setAttribute('role', 'button');
                cell.setAttribute('tabindex', '0');
                cell.setAttribute('aria-label', `Step ${col + 1}`);
                
                paintCellVelocity(cell, row, col);
                if (state.grids[state.activeTrack][row][col]) {
                    cell.classList.add('active-step');
                }

                // Touch sequencer: tap toggles, vertical drag paints velocity.
                attachTouchCell(cell, row, col);

                rowDiv.appendChild(cell);
            }
            gridContainer.appendChild(rowDiv);
        }

        // Apply grid styling tag to container so the correct active color triggers
        const sequencerWrapper = document.querySelector('.sequencer-container');
        sequencerWrapper.className = `sequencer-container ${state.activeTrack}-mode`;
        syncPocketTracks();
        window.dispatchEvent(new Event('studio-grid-rebuilt'));
    }

function paintCellVelocity(cellElement, row, col) {
        const v = state.vel[state.activeTrack][row][col];
        cellElement.style.setProperty('--vel', v.toFixed(2));
        cellElement.setAttribute('aria-pressed', state.grids[state.activeTrack][row][col] ? 'true' : 'false');
    }

function applyVelocity(row, col, cellElement, v) {
        const nv = Math.max(0.15, Math.min(1, v));
        state.vel[state.activeTrack][row][col] = nv;
        if (!state.grids[state.activeTrack][row][col]) {
            state.grids[state.activeTrack][row][col] = true;
            cellElement.classList.add('active-step');
        }
        paintCellVelocity(cellElement, row, col);
    }

// Tap = toggle. Vertical drag on a pad = velocity fader (drag up = louder).
    function attachTouchCell(cellElement, row, col) {
        let tracking = null;

        cellElement.addEventListener('pointerdown', (e) => {
            initAudio();
            try { cellElement.setPointerCapture(e.pointerId); } catch (_) {}
            tracking = {
                id: e.pointerId,
                startY: e.clientY,
                startVel: state.vel[state.activeTrack][row][col],
                wasActive: state.grids[state.activeTrack][row][col],
                dragged: false
            };
        });

        cellElement.addEventListener('pointermove', (e) => {
            if (!tracking || e.pointerId !== tracking.id) return;
            const dy = tracking.startY - e.clientY;
            if (Math.abs(dy) > 12) {
                tracking.dragged = true;
                cellElement.classList.add('vel-drag');
                applyVelocity(row, col, cellElement, tracking.startVel + dy / 140);
            }
        });

        const finish = (e) => {
            if (!tracking || (e && e.pointerId !== tracking.id)) return;
            const wasDrag = tracking.dragged;
            tracking = null;
            cellElement.classList.remove('vel-drag');
            if (!wasDrag) {
                toggleCell(row, col, cellElement);
            }
        };

        cellElement.addEventListener('pointerup', finish);
        cellElement.addEventListener('pointercancel', () => {
            tracking = null;
            cellElement.classList.remove('vel-drag');
        });

        // Keyboard access: Enter/Space toggles focused pad.
        cellElement.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                e.stopPropagation();
                toggleCell(row, col, cellElement);
            }
        });

        // Prevent iOS double-tap zoom / context menu on long press.
        cellElement.addEventListener('contextmenu', (e) => e.preventDefault());
    }

function toggleCell(row, col, cellElement) {
        initAudio();
        const activeGrid = state.grids[state.activeTrack];
        activeGrid[row][col] = !activeGrid[row][col];
        
        if (activeGrid[row][col]) {
            cellElement.classList.add('active-step');
            if (state.vel[state.activeTrack][row][col] < 0.15) {
                state.vel[state.activeTrack][row][col] = 0.8;
            }
            paintCellVelocity(cellElement, row, col);
            // Play note trigger feedback instantly when clicking (with velocity)
            playSynthNote(state.activeTrack, row, audioCtx.currentTime, state.vel[state.activeTrack][row][col]);
        } else {
            cellElement.classList.remove('active-step');
            paintCellVelocity(cellElement, row, col);
        }
    }

function highlightPlayheadColumn(stepIndex) {
        // Toggle indicators at the top
        for (let s = 0; s < NUM_STEPS; s++) {
            const node = document.getElementById(`step-node-${s}`);
            if (node) {
                if (s === stepIndex) {
                    node.classList.add('active-playhead');
                } else {
                    node.classList.remove('active-playhead');
                }
            }
        }

        // Highlight cells in grid
        for (let row = 0; row < NUM_ROWS; row++) {
            const rowDiv = document.getElementById(`grid-row-${row}`);
            if (rowDiv) {
                for (let col = 0; col < NUM_STEPS; col++) {
                    const cell = rowDiv.children[col];
                    if (cell) {
                        if (col === stepIndex) {
                            cell.classList.add('active-playhead-step');
                            if (cell.classList.contains('active-step')) {
                                rowDiv.classList.add('playhead-col-active');
                            }
                        } else {
                            cell.classList.remove('active-playhead-step');
                        }
                    }
                }
            }
        }
    }

function removePlayheadHighlights() {
        for (let s = 0; s < NUM_STEPS; s++) {
            const node = document.getElementById(`step-node-${s}`);
            if (node) node.classList.remove('active-playhead');
        }

        for (let row = 0; row < NUM_ROWS; row++) {
            const rowDiv = document.getElementById(`grid-row-${row}`);
            if (rowDiv) {
                rowDiv.classList.remove('playhead-col-active');
                for (let col = 0; col < NUM_STEPS; col++) {
                    const cell = rowDiv.children[col];
                    if (cell) cell.classList.remove('active-playhead-step');
                }
            }
        }
    }



    function applyMuteToMaster() {
        if (audioCtx && masterGain) {
            masterGain.gain.setValueAtTime(isMuted ? 0 : 0.8, audioCtx.currentTime);
        }
    }

function setMuted(m) {
        isMuted = !!m;
        applyMuteToMaster();
        return isMuted;
    }

function toggleMute() {
        return setMuted(!isMuted);
    }

function getNoiseBuffer() {
        if (!audioCtx) return null;
        if (noiseBuffer) return noiseBuffer;
        
        const bufferSize = audioCtx.sampleRate * 2;
        const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        noiseBuffer = buffer;
        return noiseBuffer;
    }

// Update synth parameter node values dynamically
    function updateSynthParameters() {
        if (!audioCtx) return;
        
        const now = audioCtx.currentTime;
        mainFilter.frequency.setValueAtTime(state.settings.cutoff, now);
        mainFilter.Q.setValueAtTime(state.settings.resonance, now);
        
        delayNode.delayTime.setValueAtTime(state.settings.delayTime, now);
        delayFeedbackNode.gain.setValueAtTime(state.settings.delayFeedback, now);
        delayGainNode.gain.setValueAtTime(state.settings.delayGain, now);
        
        reverbGainNode.gain.setValueAtTime(state.settings.reverbGain, now);
    }

function playClap(time, v) {
        const vv = Math.max(0.15, Math.min(1, typeof v === 'number' ? v : 1));
        // Multi-trigger white noise bursts
        const duration = 0.28;
        const source = audioCtx.createBufferSource();
        source.buffer = getNoiseBuffer();

        const filter = audioCtx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.frequency.value = 1500;
        
        const gain = audioCtx.createGain();
        
        // 3 quick pre-bursts + final decay tail (scaled by velocity)
        const peak = 0.12 + 0.48 * vv;
        gain.gain.setValueAtTime(peak, time);
        gain.gain.setValueAtTime(0.01, time + 0.01);
        gain.gain.setValueAtTime(peak, time + 0.02);
        gain.gain.setValueAtTime(0.01, time + 0.03);
        gain.gain.setValueAtTime(peak, time + 0.04);
        gain.gain.setValueAtTime(0.01, time + 0.05);
        gain.gain.setValueAtTime(peak * 1.1, time + 0.06);
        gain.gain.exponentialRampToValueAtTime(0.001, time + duration);

        source.connect(filter);
        filter.connect(gain);
        gain.connect(channels.drums.gain);

        source.start(time);
        source.stop(time + duration);
    }

function playRimshot(time, v) {
        const vv = Math.max(0.15, Math.min(1, typeof v === 'number' ? v : 1));
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = 'square';
        osc.frequency.setValueAtTime(600, time);
        osc.frequency.exponentialRampToValueAtTime(100, time + 0.04);

        gain.gain.setValueAtTime(0.08 + 0.32 * vv, time);
        gain.gain.exponentialRampToValueAtTime(0.001, time + 0.04);

        osc.connect(gain);
        gain.connect(channels.drums.gain);

        osc.start(time);
        osc.stop(time + 0.04);
    }

function updateSlidersAndDropdowns() {
        // Tempo UI update
        document.getElementById('input-bpm').value = state.bpm;
        document.getElementById('label-bpm').textContent = state.bpm + ' BPM';

        // Synth Controls UI updates
        document.getElementById('param-cutoff').value = state.settings.cutoff;
        document.getElementById('display-cutoff').textContent = state.settings.cutoff + ' Hz';
        
        document.getElementById('param-q').value = state.settings.resonance;
        document.getElementById('display-q').textContent = state.settings.resonance.toFixed(1);
        
        document.getElementById('param-decay').value = state.settings.decay;
        document.getElementById('display-decay').textContent = state.settings.decay + 's';
        
        document.getElementById('param-waveform').value = state.settings.waveform;
        
        document.getElementById('param-delay-gain').value = state.settings.delayGain;
        document.getElementById('display-delay-gain').textContent = Math.round(state.settings.delayGain * 100) + '%';
        
        document.getElementById('param-delay-feedback').value = state.settings.delayFeedback;
        document.getElementById('display-delay-feedback').textContent = Math.round(state.settings.delayFeedback * 100) + '%';
        
        document.getElementById('param-delay-time').value = state.settings.delayTime;
        document.getElementById('display-delay-time').textContent = state.settings.delayTime + 's';
        
        document.getElementById('param-reverb').value = state.settings.reverbGain;
        document.getElementById('display-reverb').textContent = Math.round(state.settings.reverbGain * 100) + '%';

        // Track mixer updates
        TRACKS.forEach(track => {
            const strip = document.querySelector(`.track-channel[data-track="${track}"]`);
            if (strip) {
                strip.querySelector('.channel-vol').value = state.settings.vol[track];
                strip.querySelector('.channel-pan').value = state.settings.pan[track];
            }
        });

        // Trigger mixer nodes values updates
        if (audioCtx) {
            TRACKS.forEach(t => {
                if (channels[t].gain) {
                    channels[t].gain.gain.value = state.settings.vol[t];
                }
                if (channels[t].panner) {
                    channels[t].panner.pan.value = state.settings.pan[t];
                }
            });
            updateSynthParameters();
        }

        // Rebuild steps UI
        buildSequencerUI();
        syncPocketFX();
        syncPocketBpm();
    }

// ---- Pocket studio (mobile) helpers ----
    function setActiveTrack(track) {
        if (!TRACKS.includes(track)) return;
        state.activeTrack = track;
        document.querySelectorAll('.track-channel').forEach(s => {
            s.classList.toggle('active', s.dataset.track === track);
        });
        buildSequencerUI();
    }

function syncPocketTracks() {
        document.querySelectorAll('.pocket-pad').forEach(p => {
            const on = p.dataset.track === state.activeTrack;
            p.classList.toggle('is-active', on);
            p.setAttribute('aria-selected', on ? 'true' : 'false');
        });
    }

function fmtCutoff(hz) {
        return hz >= 1000 ? (hz / 1000).toFixed(1) + 'k' : Math.round(hz) + '';
    }

function syncPocketFX() {
        const map = [
            ['pocket-cutoff', 'pocket-cutoff-val', state.settings.cutoff, (v) => fmtCutoff(v)],
            ['pocket-decay', 'pocket-decay-val', state.settings.decay, (v) => Number(v).toFixed(2) + 's'],
            ['pocket-echo', 'pocket-echo-val', state.settings.delayGain, (v) => Math.round(v * 100) + '%'],
            ['pocket-space', 'pocket-space-val', state.settings.reverbGain, (v) => Math.round(v * 100) + '%']
        ];
        map.forEach(([id, labelId, val, fmt]) => {
            const el = document.getElementById(id);
            const lab = document.getElementById(labelId);
            if (el && document.activeElement !== el) el.value = val;
            if (lab) lab.textContent = fmt(val);
        });
    }

function syncPocketBpm() {
        const bpmEl = document.getElementById('input-bpm');
        const bpmLab = document.getElementById('label-bpm');
        const pVal = document.getElementById('pocket-bpm-val');
        if (bpmEl && document.activeElement !== bpmEl) bpmEl.value = state.bpm;
        if (bpmLab) bpmLab.textContent = state.bpm + ' BPM';
        if (pVal) pVal.textContent = state.bpm;
    }

function setBpm(next) {
        state.bpm = Math.max(60, Math.min(200, Math.round(next)));
        syncPocketBpm();
    }

function clearActiveTrack() {
        const grid = state.grids[state.activeTrack];
        const vels = state.vel[state.activeTrack];
        for (let r = 0; r < NUM_ROWS; r++) {
            grid[r].fill(false);
            vels[r].fill(1);
        }
        buildSequencerUI();
    }

function loadPreset(name) {
        const preset = PRESETS[name];
        if (!preset) return;
        
        state.bpm = preset.bpm;
        
        // Deep copy grids (velocities reset to full — tap a pad then drag for dynamics)
        TRACKS.forEach(t => {
            for (let r = 0; r < NUM_ROWS; r++) {
                state.grids[t][r] = [...preset.grids[t][r]];
                state.vel[t][r] = preset.grids[t][r].map(on => (on ? 0.9 : 1));
            }
        });

        // Copy settings
        Object.keys(preset.settings).forEach(key => {
            if (typeof preset.settings[key] === 'object') {
                state.settings[key] = { ...preset.settings[key] };
            } else {
                state.settings[key] = preset.settings[key];
            }
        });

        updateSlidersAndDropdowns();
    }

function setupEventListeners() {
        window.addEventListener('pointerdown', initAudio, { once: true });

        // Start Overlay
        document.getElementById('btn-start-studio').addEventListener('click', () => {
            initAudio();
            document.getElementById('start-screen').classList.add('hidden');
        });

        // Transport
        document.getElementById('btn-play-stop').addEventListener('click', toggleSequencer);
        document.getElementById('btn-clear-track').addEventListener('click', clearActiveTrack);
        document.getElementById('btn-reset-all').addEventListener('click', resetAll);
        
        // Share & Preset Songs
        document.getElementById('btn-share-song').addEventListener('click', shareSong);
        document.getElementById('select-preset').addEventListener('change', (e) => {
            if (e.target.value) {
                loadPreset(e.target.value);
            }
        });

        // BPM slider
        document.getElementById('input-bpm').addEventListener('input', (e) => {
            state.bpm = parseInt(e.target.value);
            document.getElementById('label-bpm').textContent = state.bpm + ' BPM';
            syncPocketBpm();
        });

        // Pocket studio pads (thumb track switcher)
        document.querySelectorAll('.pocket-pad').forEach(pad => {
            pad.addEventListener('click', () => {
                initAudio();
                setActiveTrack(pad.dataset.track);
            });
        });

        // Pocket big transport
        const pocketPlay = document.getElementById('btn-pocket-play');
        if (pocketPlay) pocketPlay.addEventListener('click', toggleSequencer);
        const pocketClear = document.getElementById('btn-pocket-clear');
        if (pocketClear) pocketClear.addEventListener('click', clearActiveTrack);
        const bpmDown = document.getElementById('pocket-bpm-down');
        const bpmUp = document.getElementById('pocket-bpm-up');
        if (bpmDown) bpmDown.addEventListener('click', () => setBpm(state.bpm - 2));
        if (bpmUp) bpmUp.addEventListener('click', () => setBpm(state.bpm + 2));

        // Pocket thumb FX faders (two-way synced with main synth controls)
        const pocketCutoff = document.getElementById('pocket-cutoff');
        if (pocketCutoff) pocketCutoff.addEventListener('input', (e) => {
            state.settings.cutoff = parseInt(e.target.value);
            document.getElementById('param-cutoff').value = state.settings.cutoff;
            document.getElementById('display-cutoff').textContent = state.settings.cutoff + ' Hz';
            if (audioCtx) updateSynthParameters();
            syncPocketFX();
        });
        const pocketDecay = document.getElementById('pocket-decay');
        if (pocketDecay) pocketDecay.addEventListener('input', (e) => {
            state.settings.decay = parseFloat(e.target.value);
            document.getElementById('param-decay').value = state.settings.decay;
            document.getElementById('display-decay').textContent = state.settings.decay + 's';
            syncPocketFX();
        });
        const pocketEcho = document.getElementById('pocket-echo');
        if (pocketEcho) pocketEcho.addEventListener('input', (e) => {
            state.settings.delayGain = parseFloat(e.target.value);
            document.getElementById('param-delay-gain').value = state.settings.delayGain;
            document.getElementById('display-delay-gain').textContent = Math.round(state.settings.delayGain * 100) + '%';
            if (audioCtx) updateSynthParameters();
            syncPocketFX();
        });
        const pocketSpace = document.getElementById('pocket-space');
        if (pocketSpace) pocketSpace.addEventListener('input', (e) => {
            state.settings.reverbGain = parseFloat(e.target.value);
            document.getElementById('param-reverb').value = state.settings.reverbGain;
            document.getElementById('display-reverb').textContent = Math.round(state.settings.reverbGain * 100) + '%';
            if (audioCtx) updateSynthParameters();
            syncPocketFX();
        });

        // Track channel strips selectors & sliders
        document.querySelectorAll('.track-channel').forEach(channelStrip => {
            const trackName = channelStrip.dataset.track;
            
            // Select channel strip on click
            channelStrip.addEventListener('click', (e) => {
                if (e.target.tagName === 'INPUT') return; // let faders trigger separately
                
                document.querySelectorAll('.track-channel').forEach(s => s.classList.remove('active'));
                channelStrip.classList.add('active');
                
                state.activeTrack = trackName;
                buildSequencerUI();
                syncPocketTracks();
            });

            // Volume fader
            channelStrip.querySelector('.channel-vol').addEventListener('input', (e) => {
                const vol = parseFloat(e.target.value);
                state.settings.vol[trackName] = vol;
                if (channels[trackName].gain) {
                    channels[trackName].gain.gain.setValueAtTime(vol, audioCtx.currentTime);
                }
            });

            // Pan fader
            channelStrip.querySelector('.channel-pan').addEventListener('input', (e) => {
                const pan = parseFloat(e.target.value);
                state.settings.pan[trackName] = pan;
                if (channels[trackName].panner) {
                    channels[trackName].panner.pan.setValueAtTime(pan, audioCtx.currentTime);
                }
            });
        });

        // Dynamic synth control sliders
        document.getElementById('param-cutoff').addEventListener('input', (e) => {
            state.settings.cutoff = parseInt(e.target.value);
            document.getElementById('display-cutoff').textContent = state.settings.cutoff + ' Hz';
            if (audioCtx) updateSynthParameters();
            syncPocketFX();
        });

        document.getElementById('param-q').addEventListener('input', (e) => {
            state.settings.resonance = parseFloat(e.target.value);
            document.getElementById('display-q').textContent = state.settings.resonance.toFixed(1);
            if (audioCtx) updateSynthParameters();
        });

        document.getElementById('param-decay').addEventListener('input', (e) => {
            state.settings.decay = parseFloat(e.target.value);
            document.getElementById('display-decay').textContent = state.settings.decay + 's';
            syncPocketFX();
        });

        document.getElementById('param-waveform').addEventListener('change', (e) => {
            state.settings.waveform = e.target.value;
        });

        document.getElementById('param-delay-gain').addEventListener('input', (e) => {
            state.settings.delayGain = parseFloat(e.target.value);
            document.getElementById('display-delay-gain').textContent = Math.round(state.settings.delayGain * 100) + '%';
            if (audioCtx) updateSynthParameters();
            syncPocketFX();
        });

        document.getElementById('param-delay-feedback').addEventListener('input', (e) => {
            state.settings.delayFeedback = parseFloat(e.target.value);
            document.getElementById('display-delay-feedback').textContent = Math.round(state.settings.delayFeedback * 100) + '%';
            if (audioCtx) updateSynthParameters();
        });

        document.getElementById('param-delay-time').addEventListener('input', (e) => {
            state.settings.delayTime = parseFloat(e.target.value);
            document.getElementById('display-delay-time').textContent = state.settings.delayTime + 's';
            if (audioCtx) updateSynthParameters();
        });

        document.getElementById('param-reverb').addEventListener('input', (e) => {
            state.settings.reverbGain = parseFloat(e.target.value);
            document.getElementById('display-reverb').textContent = Math.round(state.settings.reverbGain * 100) + '%';
            if (audioCtx) updateSynthParameters();
            syncPocketFX();
        });

        // Keyboard triggers
        document.addEventListener('keydown', (e) => {
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;

            if (e.code === 'Space') {
                e.preventDefault();
                toggleSequencer();
            }
            if (e.code === 'KeyC') {
                e.preventDefault();
                clearActiveTrack();
            }
            if (e.code === 'KeyR') {
                e.preventDefault();
                resetAll();
            }
        });
    }

